import{_ as a,c as t,ag as o,o as i}from"./chunks/framework.kMCHP7uL.js";const _=JSON.parse('{"title":"貢獻者公約","description":"","frontmatter":{"outline":"deep","comments":false,"showVersion":false},"headers":[],"relativePath":"appendix/contributor-covenant.md","filePath":"appendix/contributor-covenant.md"}'),r={name:"appendix/contributor-covenant.md"};function n(l,e,p,c,s,d){return i(),t("div",null,e[0]||(e[0]=[o('<h1 id="貢獻者公約" tabindex="-1">貢獻者公約 <a class="header-anchor" href="#貢獻者公約" aria-label="Permalink to &quot;貢獻者公約&quot;">​</a></h1><blockquote><p>本項目採用 <a href="https://www.contributor-covenant.org/version/2/0/code_of_conduct/" target="_blank" rel="noreferrer">Contributor Covenant 2.0</a> 指導行為準則 —— 明確社區的價值觀，致力於為每個人創造熱情和安全的環境</p></blockquote><p>我們的目標是為 Zig 中文環境創造一個令人滿意舒適的交流環境，希望無論是讀者還是本項目的貢獻者均能友好交流，共同建設開放、多元、包容性強的社區！</p><h2 id="貢獻者準則" tabindex="-1">貢獻者準則 <a class="header-anchor" href="#貢獻者準則" aria-label="Permalink to &quot;貢獻者準則&quot;">​</a></h2><ul><li><p>請貢獻者互相尊重，無論背景、身份或觀點如何，我們希望創建一個友好和尊重的環境，讓每個人都能感到舒適和歡迎。</p></li><li><p>保證質量，確保貢獻是準確、清晰和易於理解的。</p></li><li><p>尊重他人創作，請確保你的貢獻是原創已得到了作者許可。</p></li><li><p>適當的語言，請避免使用冒犯或不適當的語言。</p></li><li><p>適時的反饋，如果對其他人的貢獻有任何反饋或建議，請以尊重和建設性的方式提出。</p></li></ul><h2 id="嚴禁行為" tabindex="-1">嚴禁行為 <a class="header-anchor" href="#嚴禁行為" aria-label="Permalink to &quot;嚴禁行為&quot;">​</a></h2><ul><li><p>發佈與性有關的言論或圖像，以及任何形式的獻殷勤或勾引。</p></li><li><p>挑釁行為、侮辱或貶損的言論、人身及政治攻擊。</p></li><li><p>公開或私下騷擾。</p></li><li><p>未獲明確授權擅自發布他人的資料，如地址、電子郵箱等。</p></li><li><p>其他有理由認定為違反職業操守的不當行為。</p></li></ul>',7)]))}const h=a(r,[["render",n]]);export{_ as __pageData,h as default};
